import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { motion } from 'framer-motion';
// DeepSeek ve LLaMA servisleri yerine OpenAI servislerini kullanacağız
import { getCombinedAuraDataFromOpenAI } from '../../services/openaiService';
import { saveAuraStory } from '../../services/auraDataService';
// JSON dosyasından ruh hali quiz verilerini doğrudan alıyoruz
import moodQuizData from '../../data/quizzes/moodQuiz.json';

// Quiz sorusu ve Quiz cevap seçeneği tipleri
interface QuizOption {
  id: string;
  value: string;
  [key: string]: any; // Diğer olası alanlar için
}

interface QuizQuestion {
  id: number;
  question: string;
  options: QuizOption[];
}

// Quiz cevabı için tip tanımlaması
interface DetailedAnswer {
  questionId: number;
  question: string;
  answerId: string;
  answerText: string;
}

// Yükleme animasyonu bileşeni
const LoadingAnimation = ({ text, color }: { text: string, color?: string }) => (
  <div className="loading-crystal">
    <div 
      className="loading-crystal-spinner" 
      style={{ 
        background: color || 'linear-gradient(135deg, #FF61D2, #FE9090)'
      }}
    ></div>
    <div className="loading-crystal-text">
      {text}<span className="loading-crystal-dots"></span>
    </div>
  </div>
);

// İçgörü yükleme bileşeni - daha özel animasyonlu versiyon
const InsightLoadingSkeleton = ({ icon, title, color }: { icon: string, title: string, color?: string }) => (
  <div className="insight-loading-skeleton">
    <div className="insight-loading-icon-container">
      <div 
        className="insight-loading-icon-placeholder" 
        style={{ background: color || 'linear-gradient(135deg, #FF61D2, #FE9090)' }}
      >
        <span className="insight-loading-icon">{icon}</span>
      </div>
    </div>
    <h3 className="insight-loading-title">{title}</h3>
    <div className="insight-loading-content-placeholder">
      <div className="insight-loading-crystal-container">
        <div className="insight-loading-crystal"></div>
      </div>
      <p className="insight-loading-text">İçgörüler yükleniyor<span className="insight-loading-dots"></span></p>
    </div>
  </div>
);

// Ana durum (mood) renkleri
const moodGradients = {
  main: 'linear-gradient(135deg, #43C6AC, #F8FFAE)',
  dark: 'linear-gradient(135deg, #2B7F6E, #A5AB4A)',
  light: '#43C6AC'
};

// Duygu Durum Analizi Sonuç Sayfası
const MoodResult: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [isLoading, setIsLoading] = useState(true);
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [loadingProgress, setLoadingProgress] = useState(0);
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [isAnalysisStarted, setIsAnalysisStarted] = useState(false);
  const [moodStory, setMoodStory] = useState<string>('');
  const [moodStrengths, setMoodStrengths] = useState<string>('');
  const [moodPotential, setMoodPotential] = useState<string>('');
  const [moodThinking, setMoodThinking] = useState<string>('');
  const [moodTitle, setMoodTitle] = useState<string>('');
  const [auraId, setAuraId] = useState<string | null>(null);
  const [showShareButton, setShowShareButton] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [isStoryLoading, setIsStoryLoading] = useState(true);
  const [isInsightsLoading, setIsInsightsLoading] = useState(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [expandedCard, setExpandedCard] = useState<string | null>(null);
  const [openModal, setOpenModal] = useState<string | null>(null);
  const [modalTitle, setModalTitle] = useState<string>('');
  const [modalContent, setModalContent] = useState<React.ReactNode | null>(null);
  const [modalIcon, setModalIcon] = useState<string>('');

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 50) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Yükleme animasyonu
  useEffect(() => {
    // Doğrudan sayfaya yönlendirildiğinde animasyonu 100'e çıkarma
    // loadingInterval kaldırıldı, doğrudan sayfa üzerinde yükleme gösterilecek
    setLoadingProgress(100);
  }, []);

  // Konum durum verilerini al
  useEffect(() => {
    const state = location.state as { answers: { [key: number]: string }; quizType: string } | null;

    if (!state || !state.answers) {
      // Eğer cevaplar yoksa ana sayfaya yönlendir
      navigate('/');
      return;
    }

    const quizType = 'mood'; // Bu sayfada sabit olarak 'mood' kullanılacak

    // Kullanıcı adını localStorage'dan al veya varsayılan
    const username = localStorage.getItem('auralize_username') || 'Seyyah';

    // Timeout kontrolü için
    let isTimedOut = false;
    let maxTimeout = 300000; // 5 dakika timeout

    const generateMoodAnalysis = async () => {
      setIsAnalysisStarted(true);
      timerRef.current = setTimeout(() => {
        if (isStoryLoading || isInsightsLoading) {
          isTimedOut = true;
          console.warn("Duygu durum analizi zaman aşımına uğradı");
          setMoodStory("Duygu durum analiziniz için sunucu yanıt vermedi. Bu genellikle geçici bir sorundur. Lütfen daha sonra tekrar deneyin.");
          setMoodStrengths("Zaman aşımı nedeniyle duygusal güçlü yönleriniz yüklenemedi.");
          setMoodPotential("Zaman aşımı nedeniyle duygusal potansiyeliniz yüklenemedi.");
          setMoodThinking("Zaman aşımı nedeniyle duygusal tepki stiliniz yüklenemedi.");
          setMoodTitle("Duygu Durum Analizi (Oluşturulamadı)");
          setIsStoryLoading(false);
          setIsInsightsLoading(false);
          setIsLoading(false);
        }
      }, maxTimeout);

      try {
        // Quiz cevaplarını daha detaylı bir formata dönüştür
        const detailedAnswers = Object.entries(state.answers).map(([questionId, answerId]) => {
          // moodQuizData dizisinden ilgili soruyu bul
          const question = moodQuizData.find((q: QuizQuestion) => q.id === parseInt(questionId));
          if (!question) return null;

          // Sorunun cevap seçeneklerinden kullanıcının seçtiğini bul
          const selectedOption = question.options.find((opt: QuizOption) => opt.id === answerId);
          if (!selectedOption) return null;

          return {
            questionId: parseInt(questionId),
            question: question.question,
            answerId: answerId,
            answerText: selectedOption.value
          };
        }).filter(Boolean) as DetailedAnswer[]; // null değerleri filtrele ve tip ataması yap

        console.log("Detaylı ruh hali analiz cevapları:", detailedAnswers);

        // Tek API isteği ile tüm verileri al
        const combinedDataPromise = getCombinedAuraDataFromOpenAI(quizType, username, state.answers);

        // Veriyi işleme
        combinedDataPromise.then((combinedData) => {
          if (isTimedOut) return;

          // Hikaye verisi
          setMoodStory(combinedData.story);
          setIsStoryLoading(false);

          // İçgörüler
          setMoodStrengths(combinedData.strengths);
          setMoodPotential(combinedData.potential);
          setMoodThinking(combinedData.thinkingStyle);
          setMoodTitle(combinedData.auraTitle);
          setIsInsightsLoading(false);

          // İlerleme çubuğunu güncelle
          setLoadingProgress(100);

          // Analiz verilerini kaydet
          const userId = localStorage.getItem('auralize_user_id') || Date.now().toString();
          localStorage.setItem('auralize_user_id', userId);

          try {
            saveAuraStory(userId, {
              auraType: quizType,
              story: combinedData.story || "Hikaye yüklenemedi",
              strengths: combinedData.strengths || "Güçlü yönler yüklenemedi",
              potential: combinedData.potential || "Potansiyel yüklenemedi",
              thinkingStyle: combinedData.thinkingStyle || "Düşünme stili yüklenemedi",
              auraTitle: combinedData.auraTitle || "Duygu Durum Analizi",
              answers: state.answers
            }).then((savedAuraId) => {
              setAuraId(savedAuraId);
              setShowShareButton(true);
              clearTimeout(timerRef.current as ReturnType<typeof setTimeout>);
              setIsLoading(false);
            });
          } catch (saveError) {
            console.error("Analiz kaydedilirken hata:", saveError);
            setIsLoading(false);
          }
        }).catch((error) => {
          console.error("Veri alınırken hata:", error);

          // Network hatası mı kontrol et
          if (error instanceof Error) {
            if ('message' in error && typeof error.message === 'string') {
              if (error.message.includes('network') || error.message.includes('Network') || 
                  error.message.includes('timeout') || error.message.includes('Timeout')) {
                setMoodStory("Sunucuyla iletişim kurarken bir ağ hatası oluştu. İnternet bağlantınızı kontrol edip tekrar deneyin.");
              } else {
                setMoodStory("Duygu durum analiziniz oluşturulurken teknik bir sorun yaşandı. Lütfen daha sonra tekrar deneyin.");
              }
            } else {
              setMoodStory("Duygu durum analiziniz oluşturulurken bir sorun yaşandı. Lütfen daha sonra tekrar deneyin.");
            }
          } else {
            setMoodStory("Duygu durum analiziniz oluşturulurken bir sorun yaşandı. Lütfen daha sonra tekrar deneyin.");
          }

          setMoodStrengths("Duygusal güçlü yönleriniz şu anda görüntülenemiyor.");
          setMoodPotential("Duygusal potansiyeliniz şu anda görüntülenemiyor.");
          setMoodThinking("Duygusal tepki stiliniz şu anda görüntülenemiyor.");
          setMoodTitle("Duygu Durum Analizi");

          setIsStoryLoading(false);
          setIsInsightsLoading(false);
          setIsLoading(false);
          clearTimeout(timerRef.current as ReturnType<typeof setTimeout>);
        });
      } catch (error) {
        console.error("Duygu analizi oluşturulurken hata:", error);

        setMoodStory("Bir hata oluştu. Lütfen daha sonra tekrar deneyin.");
        setMoodStrengths("Duygusal güçlü yönleriniz şu anda görüntülenemiyor.");
        setMoodPotential("Duygusal potansiyeliniz şu anda görüntülenemiyor.");
        setMoodThinking("Duygusal tepki stiliniz şu anda görüntülenemiyor.");
        setMoodTitle("Duygu Durum Analizi");

        clearTimeout(timerRef.current as ReturnType<typeof setTimeout>);
        setIsStoryLoading(false);
        setIsInsightsLoading(false);
        setIsLoading(false);
        setLoadingProgress(100);
      }
    };

    // İlk yükleme hemen başlasın
    generateMoodAnalysis();

    // Cleanup fonksiyonu
    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
    };
  }, [location, navigate, moodStory, moodStrengths, moodPotential, moodThinking, moodTitle, isStoryLoading, isInsightsLoading]);

  // Analizi paylaşma fonksiyonu
  const handleShareAnalysis = async () => {
    if (!auraId) return;

    setIsSharing(true);
    // Burada paylaşım işlemleri yapılabilir
    setTimeout(() => {
      navigate('/gallery', { state: { shared: true, auraId } });
    }, 1500);
  };

  // Animasyon varyantları
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const fadeInUp = {
    hidden: { opacity: 0, y: 30 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.8,
        ease: "easeOut"
      }
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const itemAnimation = {
    hidden: { opacity: 0, y: 20 },
    visible: (i: number) => ({
      opacity: 1,
      y: 0,
      transition: {
        delay: 0.3 + (i * 0.1),
        duration: 0.5,
        ease: "easeOut"
      }
    }),
  };

  // Pulse animasyonu
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const pulseAnimation = {
    scale: [1, 1.05, 1],
    opacity: [0.7, 0.9, 0.7],
    transition: {
      duration: 2,
      repeat: Infinity,
      ease: "easeInOut"
    }
  };

  // Toggle card expansion fonksiyonu
  const toggleCardExpansion = (cardId: string) => {
    if (expandedCard === cardId) {
      setExpandedCard(null);
    } else {
      setExpandedCard(cardId);
    }
  };

  // Detaylı açıklama metni alma
  const getDetailedExplanation = (cardId: string): string => {
    switch (cardId) {
      case 'strengths':
        return moodStrengths;
      case 'potential':
        return moodPotential;
      case 'thinking':
        return moodThinking;
      default:
        return '';
    }
  };

  return (
    <div className="mood-result-container">
      <style>{`
        /* Ana yükleme animasyonu */
        .aura-crystal-container {
          display: flex;
          justify-content: center;
          align-items: center;
          margin-bottom: 2rem;
          perspective: 800px;
        }

        .aura-crystal {
          width: 80px;
          height: 80px;
          position: relative;
          transform-style: preserve-3d;
          animation: crystal-rotate 4s infinite linear;
          transform: rotateX(20deg) rotateY(20deg);
        }

        .crystal-face {
          position: absolute;
          width: 100%;
          height: 100%;
          background: ${moodGradients.main};
          opacity: 0.7;
          border-radius: 15%;
        }

        .face1 { transform: rotateY(0deg) translateZ(40px); }
        .face2 { transform: rotateY(90deg) translateZ(40px); }
        .face3 { transform: rotateY(180deg) translateZ(40px); }
        .face4 { transform: rotateY(270deg) translateZ(40px); }

        .crystal-shadow {
          position: absolute;
          width: 100%;
          height: 20px;
          background: rgba(0,0,0,0.2);
          bottom: -40px;
          border-radius: 50%;
          filter: blur(10px);
          animation: shadow-pulse 2s infinite alternate;
        }

        @keyframes crystal-rotate {
          from { transform: rotateX(20deg) rotateY(0deg); }
          to { transform: rotateX(20deg) rotateY(360deg); }
        }

        @keyframes shadow-pulse {
          from { transform: scale(0.8); opacity: 0.2; }
          to { transform: scale(1); opacity: 0.4; }
        }

        /* İçgörü yükleme bileşenleri */
        .loading-crystal {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 0.8rem;
          padding: 1rem;
        }

        .loading-crystal-spinner {
          width: 40px;
          height: 40px;
          border-radius: 30%;
          position: relative;
          animation: crystal-spin 2s infinite linear;
        }

        .loading-crystal-spinner::before,
        .loading-crystal-spinner::after {
          content: '';
          position: absolute;
          width: 100%;
          height: 100%;
          border-radius: 30%;
          background: inherit;
          opacity: 0.7;
        }

        .loading-crystal-spinner::after {
          filter: blur(5px);
          animation: crystal-pulse 1.5s infinite alternate;
        }

        .loading-crystal-text {
          font-size: 0.9rem;
          color: #666;
          display: flex;
          gap: 0.2rem;
        }

        .loading-crystal-dots {
          position: relative;
          min-width: 16px;
        }

        .loading-crystal-dots::after {
          content: '...';
          position: absolute;
          animation: dots-animation 1.5s infinite;
          width: 1.5em;
        }

        @keyframes crystal-spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }

        @keyframes crystal-pulse {
          from { transform: scale(1); opacity: 0.7; }
          to { transform: scale(1.3); opacity: 0.3; }
        }

        @keyframes dots-animation {
          0%, 20% { content: '.'; }
          40% { content: '..'; }
          60%, 100% { content: '...'; }
        }

        /* İçgörü yükleme iskeleti - geliştirilmiş versiyon */
        .insight-loading-skeleton {
          padding: 1.5rem;
          border-radius: 12px;
          background: rgba(255, 255, 255, 0.7);
          backdrop-filter: blur(10px);
          box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
          height: 100%;
        }

        .insight-loading-icon-container {
          display: flex;
          justify-content: center;
          margin-bottom: 1rem;
        }

        .insight-loading-icon-placeholder {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          position: relative;
          overflow: hidden;
        }

        .insight-loading-icon-placeholder::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: inherit;
          opacity: 0.7;
          z-index: 1;
        }

        .insight-loading-icon-placeholder::after {
          content: '';
          position: absolute;
          top: -50%;
          left: -50%;
          right: -50%;
          bottom: -50%;
          background: linear-gradient(
            45deg,
            rgba(255, 255, 255, 0) 0%,
            rgba(255, 255, 255, 0.8) 50%,
            rgba(255, 255, 255, 0) 100%
          );
          transform: rotate(45deg);
          animation: insight-icon-shine 2s infinite;
          z-index: 2;
        }

        .insight-loading-icon {
          position: relative;
          z-index: 3;
          color: white;
          font-size: 1.2rem;
          text-shadow: 0 1px 3px rgba(0, 0, 0, 0.3);
        }

        @keyframes insight-icon-shine {
          0% { transform: translateX(-100%) rotate(45deg); }
          100% { transform: translateX(100%) rotate(45deg); }
        }

        .insight-loading-title {
          margin: 0 0 1rem 0;
          font-size: 1.1rem;
          color: #333;
          text-align: center;
        }

        .insight-loading-content-placeholder {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: 1rem;
          min-height: 100px;
        }

        .insight-loading-crystal-container {
          width: 100%;
          display: flex;
          justify-content: center;
          margin-bottom: 1rem;
        }

        .insight-loading-crystal {
          width: 40px;
          height: 40px;
          background: linear-gradient(135deg, #43C6AC, #F8FFAE);
          border-radius: 20%;
          position: relative;
          animation: crystal-rotate-3d 3s infinite linear;
          transform-style: preserve-3d;
          box-shadow: 0 5px 15px rgba(67, 198, 172, 0.3);
        }

        .insight-loading-crystal::before,
        .insight-loading-crystal::after {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: inherit;
          border-radius: 20%;
          opacity: 0.6;
        }

        .insight-loading-crystal::before {
          transform: rotateX(60deg);
        }

        .insight-loading-crystal::after {
          transform: rotateY(60deg);
        }

        @keyframes crystal-rotate-3d {
          0% { transform: rotate(0deg) rotateX(30deg) rotateY(0deg); }
          100% { transform: rotate(360deg) rotateX(30deg) rotateY(360deg); }
        }

        .insight-loading-text {
          font-size: 0.9rem;
          color: #666;
          display: flex;
          align-items: center;
          gap: 0.2rem;
        }

        .insight-loading-dots {
          position: relative;
          width: 2em;
          display: inline-block;
        }

        .insight-loading-dots::after {
          content: '...';
          position: absolute;
          animation: insight-dots 1.5s infinite steps(4);
          overflow: hidden;
          white-space: nowrap;
        }

        @keyframes insight-dots {
          0% { content: ''; width: 0; }
          100% { content: '...'; width: 3em; }
        }

        .mood-section {
          margin-bottom: 2rem;
        }

        .mood-section-header {
          margin-bottom: 1.5rem;
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }

        .mood-section-title {
          font-size: 1.5rem;
          font-weight: 600;
          color: #333;
        }

        .mood-insights-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
          gap: 1.5rem;
          margin-bottom: 2rem;
        }

        .mood-insight-card {
          background: rgba(255, 255, 255, 0.8);
          backdrop-filter: blur(10px);
          border-radius: 12px;
          padding: 1.5rem;
          box-shadow: 0 8px 32px rgba(0, 0, 0, 0.06);
          border: 1px solid rgba(255, 255, 255, 0.8);
          min-height: 200px;
          display: flex;
          flex-direction: column;
          gap: 1rem;
          cursor: pointer;
          transition: all 0.3s ease;
          position: relative;
          overflow: hidden;
        }

        .mood-insight-card:hover {
          transform: translateY(-5px);
          box-shadow: 0 12px 32px rgba(0, 0, 0, 0.1);
        }

        .mood-insight-icon {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: ${moodGradients.main};
          color: white;
          font-size: 1.5rem;
          margin-bottom: 0.5rem;
        }

        .mood-insight-title {
          font-size: 1.2rem;
          font-weight: 600;
          color: #333;
          margin-bottom: 0.5rem;
        }

        .mood-insight-text {
          font-size: 1rem;
          color: #666;
          line-height: 1.6;
        }

        .insight-content {
          position: relative;
          height: 150px;
          overflow: hidden;
        }

        .insight-content-gradient {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 50px;
          background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.9));
          pointer-events: none;
        }

        .insight-card-expand-hint {
          text-align: center;
          margin-top: 0.5rem;
          color: #43C6AC;
          font-weight: 500;
          font-size: 14px;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 4px;
          transition: all 0.3s ease;
          transform: translateY(5px);
          opacity: 0.7;
        }

        .mood-insight-card:hover .insight-card-expand-hint {
          transform: translateY(0);
          opacity: 1;
        }

        /* Modal stili */
        .insight-modal {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: rgba(0, 0, 0, 0.5);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 1000;
          padding: 1rem;
          animation: modalBounce 0.5s ease-out;
        }

        .modal-content {
          background: white;
          border-radius: 12px;
          max-width: 600px;
          width: 100%;
          max-height: 80vh;
          overflow-y: auto;
          padding: 2rem;
          position: relative;
          box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
        }

        .modal-close {
          position: absolute;
          top: 1rem;
          right: 1rem;
          background: none;
          border: none;
          font-size: 1.5rem;
          cursor: pointer;
          color: #aaa;
          transition: color 0.3s;
        }

        .modal-close:hover {
          color: #333;
        }

        .modal-header {
          display: flex;
          align-items: center;
          gap: 1rem;
          margin-bottom: 1.5rem;
          border-bottom: 1px solid #eee;
          padding-bottom: 1rem;
        }

        .modal-icon {
          width: 40px;
          height: 40px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: ${moodGradients.main};
          color: white;
          font-size: 1.2rem;
        }

        .modal-title {
          font-size: 1.5rem;
          font-weight: 600;
          color: #333;
        }

        .modal-body {
          font-size: 1rem;
          color: #666;
          line-height: 1.8;
        }

        .modal-body p {
          margin-bottom: 1rem;
        }

        @keyframes modalBounce {
          0% { transform: scale(0.8); opacity: 0; }
          50% { transform: scale(1.05); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
      `}</style>

      {/* Header */}
      <header className={`header mood-header ${scrolled ? 'scrolled' : ''}`}>
        <div className="container">
          <div className="flex justify-between items-center">
            <Link to="/" className="gradient-text text-2xl font-bold">
              Auralize
              <span className="logo-particle">✨</span>
            </Link>
            <nav>
              <ul className="flex space-x-6">
                <li><Link to="/gallery" className="nav-link">Galeri</Link></li>
                <li><Link to="/profile" className="nav-link">Profilim</Link></li>
              </ul>
            </nav>
          </div>
        </div>
      </header>

      <main className="main-content mood-result-content">
        <div className="container">
          <h1 className="mood-result-title">{moodTitle || 'Duygu Durum Analizi'}</h1>

          {/* Hikaye Bölümü */}
          <section className="mood-section">
            <div className="mood-section-header">
              <h2 className="mood-section-title">
                <span className="mood-section-icon">💭</span> Duygusal Durum Hikayen
              </h2>
            </div>

            <div className="mood-story-box glass-card">
              {isStoryLoading ? (
                <div className="aura-loading-container">
                  <LoadingAnimation text="Duygusal durum analiziniz hazırlanıyor" color={moodGradients.main} />
                </div>
              ) : (
                <div className="mood-story-content animate__animated animate__fadeIn">
                  <div className="mood-story-text">
                    {moodStory.split('\n\n').map((paragraph, index) => (
                      <p key={index}>{paragraph}</p>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </section>

          {/* İçgörüler Bölümü */}
          <section className="mood-section">
            <div className="mood-section-header">
              <h2 className="mood-section-title">
                <span className="mood-section-icon">💡</span> Duygu Durumu İçgörülerin
              </h2>
            </div>

            <div className="mood-insights-grid">
              <div 
                className="mood-insight-card"
                onClick={() => {
                  const formattedStrengths = moodStrengths.split('\n\n').map((paragraph, idx) => 
                    <p key={idx}>{paragraph}</p>
                  );

                  setModalContent(formattedStrengths);
                  setModalTitle('Duygusal Güçlü Yönlerin');
                  setModalIcon('🌟');
                  setOpenModal('strengths');
                }}
              >
                {isInsightsLoading ? (
                  <InsightLoadingSkeleton 
                    icon="🌟" 
                    title="Duygusal Güçlü Yönlerin" 
                    color={moodGradients.main}
                  />
                ) : (
                  <>
                    <div className="mood-insight-icon">🌟</div>
                    <h3 className="mood-insight-title">Duygusal Güçlü Yönlerin</h3>
                    <div className="insight-content">
                      <div className="insight-content-gradient"></div>
                      <p className="mood-insight-text">
                        {moodStrengths}
                      </p>
                    </div>
                    <div className="insight-card-expand-hint">
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M15 3h6v6"></path>
                        <path d="M10 14 21 3"></path>
                      </svg>
                      Daha Fazla Göster
                    </div>
                  </>
                )}
              </div>

              <div 
                className="mood-insight-card"
                onClick={() => {
                  const formattedPotential = moodPotential.split('\n\n').map((paragraph, idx) => 
                    <p key={idx}>{paragraph}</p>
                  );

                  setModalContent(formattedPotential);
                  setModalTitle('Duygusal Potansiyelin');
                  setModalIcon('🚀');
                  setOpenModal('potential');
                }}
              >
                {isInsightsLoading ? (
                  <InsightLoadingSkeleton 
                    icon="🚀" 
                    title="Duygusal Potansiyelin" 
                    color={moodGradients.main}
                  />
                ) : (
                  <>
                    <div className="mood-insight-icon">🚀</div>
                    <h3 className="mood-insight-title">Duygusal Potansiyelin</h3>
                    <div className="insight-content">
                      <div className="insight-content-gradient"></div>
                      <p className="mood-insight-text">
                        {moodPotential}
                      </p>
                    </div>
                    <div className="insight-card-expand-hint">
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M15 3h6v6"></path>
                        <path d="M10 14 21 3"></path>
                      </svg>
                      Daha Fazla Göster
                    </div>
                  </>
                )}
              </div>

              <div 
                className="mood-insight-card"
                onClick={() => {
                  const formattedThinking = moodThinking.split('\n\n').map((paragraph, idx) => 
                    <p key={idx}>{paragraph}</p>
                  );

                  setModalContent(formattedThinking);
                  setModalTitle('Duygusal Tepki Stilin');
                  setModalIcon('🧠');
                  setOpenModal('thinking');
                }}
              >
                {isInsightsLoading ? (
                  <InsightLoadingSkeleton 
                    icon="🧠" 
                    title="Duygusal Tepki Stilin" 
                    color={moodGradients.main}
                  />
                ) : (
                  <>
                    <div className="mood-insight-icon">🧠</div>
                    <h3 className="mood-insight-title">Duygusal Tepki Stilin</h3>
                    <div className="insight-content">
                      <div className="insight-content-gradient"></div>
                      <p className="mood-insight-text">
                        {moodThinking}
                      </p>
                    </div>
                    <div className="insight-card-expand-hint">
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M15 3h6v6"></path>
                        <path d="M10 14 21 3"></path>
                      </svg>
                      Daha Fazla Göster
                    </div>
                  </>
                )}
              </div>
            </div>
          </section>

          {/* Modal Component */}
          {openModal && (
            <div className="insight-modal" onClick={() => setOpenModal(null)}>
              <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <button className="modal-close" onClick={() => setOpenModal(null)}>×</button>
                <div className="modal-header">
                  <div className="modal-icon">{modalIcon}</div>
                  <h2 className="modal-title">{modalTitle}</h2>
                </div>
                <div className="modal-body">
                  {modalContent}
                </div>
              </div>
            </div>
          )}

          {/* Aksiyon Butonları */}
          <div className="mood-actions">
            <Link to="/" className="btn btn-primary">
              Ana Sayfaya Dön
            </Link>
            <Link to="/quiz?type=mood" className="btn btn-glass">
              <span className="btn-icon">🔄</span>
              Testi Tekrarla
            </Link>
            {showShareButton && (
              <button 
                className={`btn ${isSharing ? 'btn-success' : 'btn-share'}`}
                onClick={handleShareAnalysis}
                disabled={isSharing}
              >
                <span className="btn-icon">
                  {isSharing ? '✓' : (
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <circle cx="18" cy="5" r="3"></circle>
                      <circle cx="6" cy="12" r="3"></circle>
                      <circle cx="18" cy="19" r="3"></circle>
                      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49"></line>
                      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49"></line>
                    </svg>
                  )}
                </span>
                {isSharing ? 'Paylaşıldı' : 'Galeriye Paylaş'}
              </button>
            )}
          </div>
        </div>
      </main>

      <footer className="py-6 px-4 gradient-footer" style={{ background: moodGradients.dark }}>
        <div className="container">
          <div className="text-center text-white">
            <p>
              &copy; {new Date().getFullYear()} Auralize - Duygularınızı Keşfedin
              <span className="ml-2">✨</span>
            </p>
            <div className="footer-links">
              <a href="/about" className="footer-link">Hakkımızda</a>
              <a href="/privacy" className="footer-link">Gizlilik</a>
              <a href="/contact" className="footer-link">İletişim</a>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default MoodResult;
